std::env::var("HIPCORTEX_API_KEYS")
        .unwrap_or_default()
        .split(',')
        .filter_map(|entry| {
            let mut parts = entry.trim().splitn(2, ':');
            let key  = parts.next()?.to_string();
            let tier = parts.next().unwrap_or("free");
            if key.is_empty() { None } else { Some((key, ApiTier::from_str(tier))) }
        }).collect

